 # Standardize the representation of "Voluntary Non-Profit" and "Government"
 def standardize_hospital_owner(value):
     if 'voluntary' in value.lower():
         return 'Voluntary Non-Profit'.title()
     elif 'government' in value.lower():
         return 'Government'.title()
     else:
         return value

 # Remove extra spaces and special characters
 def clean_hospital_owner(value):
     return re.sub(r'\s+', ' ', value).strip().lower()

 # Apply the standardization and cleaning functions to the HospitalOwner column
 cleaned_hospital_owners = [clean_hospital_owner(hospital_owner) for hospital_owner in HospitalOwner]
 standardized_hospitals = [standardize_hospital_owner(hospital_owner) for hospital_owner in cleaned_hospital_owners]

 # Filter for hospitals owned by governments that are located in ZIP codes with multiple hospital types
 government_hospitals = []
 for i, hospital in enumerate(standardized_hospitals):
     if hospital == 'Government' and 'government' in cleaned_hospital_owners[i]:
         government_hospitals.append(cleaned_hospital_owners[i])
return value

